const fs = require("fs");
const path = require("path");
const root = "/w/node_modules/agents";
const pkg = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8"));
function distFiles() {
  const dist = path.join(root, "dist");
  return fs.readdirSync(dist).filter((f) => f.endsWith(".js")).map((f) => ({ file: f, src: fs.readFileSync(path.join(dist, f), "utf8") }));
}
const agent = distFiles().find((f) => /var Agent = class Agent extends/.test(f.src) && f.src.includes("async queue(callback, payload, options)"));
if (!agent) {
  console.error("FAIL: could not find Agent.queue() in agents " + pkg.version);
  process.exit(1);
}
const start = agent.src.indexOf("async queue(callback, payload, options)");
const body = agent.src.slice(start, start + 1200);
if (agent.src.includes("_flushQueue")) {
  console.error("FAIL: queue() drains callbacks in the isolate (_flushQueue) with the enqueuing request's connection and request");
  process.exit(1);
}
if (!body.includes("this._queue.push(callback, payload, options)")) {
  console.error("FAIL: queue() does not push to the Lifecycle Queue capability");
  process.exit(1);
}
console.log("OK: agents " + pkg.version + " queue() pushes to the Lifecycle Queue (run from the alarm loop); no in-isolate _flushQueue");

